<template><ion-page v-if="movie"><ion-header><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/tabs/home" /></ion-buttons><ion-title>Movie details</ion-title></ion-toolbar></ion-header><ion-content><div class="backdrop" :style="{ backgroundImage: `linear-gradient(0deg, var(--ion-background-color) 4%, transparent), url(${movie.poster})` }"></div><main class="details"><div class="title-row"><div><p class="eyebrow">{{ movie.genre }} · {{ movie.releaseYear }} · {{ movie.runtime }} min</p><h1>{{ movie.title }}</h1><div class="rating">★ {{ movie.rating }} / 10</div></div><ion-button fill="clear" @click="toggleFavorite(movie)"><ion-icon slot="icon-only" :icon="movie.favorite ? heart : heartOutline" /></ion-button></div><p class="description">{{ movie.description }}</p><div class="actions"><ion-button expand="block" @click="toggleWatched(movie)">{{ movie.status === 'Watched' ? 'Mark as not watched' : 'Mark as watched' }}</ion-button><ion-button expand="block" fill="outline" @click="toggleFavorite(movie)">{{ movie.favorite ? 'Remove from favorites' : 'Add to favorites' }}</ion-button></div><ion-list lines="none" class="info-list"><ion-item><ion-label><span>Director</span><strong>{{ movie.director }}</strong></ion-label></ion-item><ion-item><ion-label><span>Cast</span><strong>{{ movie.cast.join(', ') }}</strong></ion-label></ion-item><ion-item><ion-label><span>Status</span><strong>{{ movie.status }}</strong></ion-label></ion-item></ion-list><ion-button v-if="movie.trailerUrl" expand="block" fill="clear" :href="movie.trailerUrl" target="_blank">Watch trailer</ion-button></main></ion-content></ion-page><ion-page v-else><ion-content class="missing">Movie not found</ion-content></ion-page></template>
<script setup lang="ts">import { computed } from 'vue'; import { IonBackButton, IonButton, IonButtons, IonContent, IonHeader, IonIcon, IonItem, IonLabel, IonList, IonPage, IonTitle, IonToolbar } from '@ionic/vue'; import { heart, heartOutline } from 'ionicons/icons'; import { useRoute } from 'vue-router'; import { useMovieStore } from '../stores/movieStore'; const route = useRoute(); const store = useMovieStore(); const { movies, toggleFavorite, toggleWatched } = store; const movie = computed(() => movies.value.find((item) => item.id === route.params.id));</script>
<style scoped>.backdrop { height: 270px; background-size: cover; background-position: center; opacity: .82; }.details { max-width: 760px; margin: -42px auto 0; position: relative; padding: 0 20px 40px; }.title-row { display: flex; justify-content: space-between; align-items: start; }.eyebrow { color: var(--ion-color-primary); font-size: .75rem; text-transform: uppercase; letter-spacing: .07em; }.title-row h1 { font-size: 2.4rem; line-height: 1; margin: 8px 0; }.rating { color: #f4ba45; font-weight: 700; }.description { color: var(--ion-color-medium); line-height: 1.55; margin: 22px 0; }.actions { display: grid; gap: 10px; }.info-list { background: transparent; margin-top: 22px; }.info-list ion-item { --background: transparent; --padding-start: 0; border-bottom: 1px solid var(--surface-border); }.info-list span, .info-list strong { display: block; }.info-list span { color: var(--ion-color-medium); font-size: .75rem; }.info-list strong { margin-top: 4px; }.missing { display: grid; place-items: center; }</style>
